package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforceHolidaySettingsController;import com.rpb.reservation.workforce.calendar.annual.*;import static com.rpb.reservation.workforce.calendar.annual.HolidayDtos.*;import com.rpb.reservation.walkin.api.*;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class WorkforceHolidaySettingsApiTest {
 CurrentActorProvider actors=mock(CurrentActorProvider.class);PublicHolidayService years=mock(PublicHolidayService.class);StoreRestMonthService months=mock(StoreRestMonthService.class);String base="/api/v1/stores/"+UUID.randomUUID()+"/workforce";MockMvc mvc=MockMvcBuilders.standaloneSetup(new WorkforceHolidaySettingsController(actors,years,months)).build();
 @Test void readsArePrivateAndRequireAuthentication()throws Exception{for(String path:List.of("/public-holidays/2026","/public-holiday-templates/2027","/store-rest-months/2026-11"))mvc.perform(get(base+path)).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","private, no-store"));verifyNoInteractions(years,months);}
 @Test void writesKeepSameOriginProtectionAndTypedYears()throws Exception{for(String path:List.of("/public-holidays/2026","/store-rest-months/2026-11")){mvc.perform(put(base+path).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(put(base+path).header("X-RPB-Workforce","1").header("Sec-Fetch-Site","cross-site").contentType("application/json").content("{}")).andExpect(status().isForbidden());}when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));when(years.get(any(),any(),eq(2026))).thenReturn(new YearPage(2026,0,List.of()));mvc.perform(get(base+"/public-holidays/2026")).andExpect(status().isOk()).andExpect(jsonPath("$.version").value(0));mvc.perform(get(base+"/public-holidays/invalid")).andExpect(status().isBadRequest());}
}
